import type { Chart } from "chart.js";
import { scheduleRender } from "../entry/main";

/* ── Theme ───────────────────────────────────────────────────────────────────
   Colours live in styles.css as light-dark(light, dark). getComputedStyle
   returns a custom property UNRESOLVED, so each one is read off a probe's
   computed `color` and normalised through a 2d context: Chart.js needs
   #rrggbb / rgba(), not color(srgb …). THEME keeps its old shape via getters,
   so no call site changes; charts are rebuilt on every render() anyway. */

const VARS = {
  ink: "--chart-ink",
  label: "--chart-label",
  muted: "--chart-muted",
  grid: "--chart-grid",
  axisGrid: "--chart-axis-grid",
  hollow: "--chart-hollow",
  tooltipBg: "--chart-tooltip-bg",
  tooltipInk: "--chart-tooltip-ink",
  series1: "--chart-series-1",
  series2: "--chart-series-2",
  series3: "--chart-series-3",
  series4: "--chart-series-4",
  series5: "--chart-series-5",
  series6: "--chart-series-6",
  series7: "--chart-series-7",
} as const;

/* 3. regression: 0.18 was previously corrected to 0.45 for exactly this
      reason. 0.45 keeps the series legible while de-emphasised. */
export const DIM = 0.45;

/* 2. titles/subtitles were still #666 (Chart.js default) → ≈3.1:1 on dark. */
export const TEXT = {
  get title() {
    return value("ink");
  }, // 18.9:1 dark, 16.7:1 light
  get subtitle() {
    return value("label");
  }, // 8.8:1 dark
};

/* 8. repaint without losing user state: read the hidden set first */
export function repaintPreservingState(): void {
  const hidden = new Set(
    [
      ...document.querySelectorAll<HTMLButtonElement>(
        '.legend button[aria-pressed="false"]',
      ),
    ].map((b) => b.dataset.series ?? ""),
  );
  refreshTheme();
  scheduleRender();
}

type ThemeKey = keyof typeof VARS;

/* Light-mode values are the current RAMP hex, so a missing token degrades to
   today's appearance instead of to `inherit`. */
const FALLBACK: Record<ThemeKey, string> = {
  ink: "#111827",
  label: "#4b5563",
  muted: "#6b7280",
  grid: "#e5e5e5",
  axisGrid: "rgba(17, 24, 39, 0.06)",
  hollow: "#ffffff",
  tooltipBg: "rgba(17, 24, 39, 0.92)",
  tooltipInk: "#ffffff",
  series1: "#5C97C5",
  series2: "#357AB0",
  series3: "#2A6B9C",
  series4: "#1B5C92",
  series5: "#124A78",
  series6: "#0A3A63",
  series7: "#062844",
};

const ctx2d = document.createElement("canvas").getContext("2d");

function normalise(css: string, fallback: string): string {
  if (!ctx2d) return fallback;
  ctx2d.fillStyle = fallback;
  ctx2d.fillStyle = css;
  return typeof ctx2d.fillStyle === "string" ? ctx2d.fillStyle : fallback;
}

let cache: Record<ThemeKey, string> | null = null;

function read(): Record<ThemeKey, string> {
  const out = {} as Record<ThemeKey, string>;
  const probe = document.createElement("span");
  probe.setAttribute("aria-hidden", "true");
  probe.style.cssText = "position:absolute;width:0;height:0;visibility:hidden";
  (document.body ?? document.documentElement).append(probe);

  for (const key of Object.keys(VARS) as ThemeKey[]) {
    probe.style.color = `var(${VARS[key]})`;
    out[key] = normalise(getComputedStyle(probe).color, FALLBACK[key]);
  }

  probe.remove();
  return out;
}

const value = (key: ThemeKey): string => ((cache ??= read()), cache[key]);

/* 4. one ordered array for the trellis, so the ramp can never drift from CSS */
export const SERIES: readonly string[] = [
  "series1",
  "series2",
  "series3",
  "series4",
  "series5",
  "series6",
  "series7",
].map((k) => value(k as ThemeKey));

/** Drop the resolved colours; theme.ts calls this before re-rendering. */
export function refreshTheme(): void {
  cache = null;
}

export const THEME = {
  get ink() {
    return value("ink");
  },
  get label() {
    return value("label");
  },
  get muted() {
    return value("muted");
  },
  get grid() {
    return value("grid");
  },
  get axisGrid() {
    return value("axisGrid");
  },
  get hollow() {
    return value("hollow");
  },
  get tooltipBg() {
    return value("tooltipBg");
  },
  get tooltipInk() {
    return value("tooltipInk");
  },
  dim: 0.45, // was 0.18 — ≈1.3:1 against both modes (WCAG 1.4.1)
};

const SERIES_KEYS = [
  "series1",
  "series2",
  "series3",
  "series4",
  "series5",
  "series6",
  "series7",
] as const satisfies readonly ThemeKey[];

/** Index access for the trellis loop: never cache the result across renders. */
function seriesColor(i: number): string {
  const last = SERIES_KEYS.length - 1;
  return value(SERIES_KEYS[Math.min(Math.max(i, 0), last)]);
}

const DASHES: readonly number[][] = [
  [],
  [6, 3],
  [2, 3],
  [8, 3, 2, 3],
  [1.5, 3],
  [10, 4],
  [4, 3],
];

/** Per-episode encoding: shade + dash. `color` is a getter, so it is resolved
 *  on every chart build — after refreshTheme(), and never during module init.
 *  Call sites keep working unchanged: `RAMP[i].color`, `RAMP[i].dash`. */
export const RAMP: readonly {
  readonly color: string;
  readonly dash: number[];
}[] = DASHES.map((dash, i) => ({
  get color(): string {
    return seriesColor(i);
  },
  dash,
}));

/** #rrggbb → rgba(). Throws instead of emitting `rgba(NaN, …)`. */
export function alpha(hex: string, a: number): string {
  const m = /^#([0-9a-f]{6})$/i.exec(hex);
  if (!m) throw new Error(`alpha() expects #rrggbb, got "${hex}"`);
  const n = Number.parseInt(m[1], 16);
  return `rgba(${(n >> 16) & 255}, ${(n >> 8) & 255}, ${n & 255}, ${a})`;
}

/* ── Segment geometry ────────────────────────────────────────────────────────
   Two facts about Chart.js v4 that the old code got wrong:

   1. A point element has BOTH `.x`/`.y` (canvas pixels) and `.parsed` (scale
      values). Comparing `.x` between endpoints measures pixels, so every
      segment looks like a gap and the whole line is dashed.

   2. `segment.borderDash` is resolved for EVERY ADJACENT PAIR of data indices,
      not once per visible connector, and the resolved styles are then snapped
      onto non-skipped points. With `spanGaps: true` a pair that straddles
      empty slots is still evaluated on its own, so "does this pair jump more
      than one slot" is always false. The question has to be asked about the
      CONNECTOR — the nearest visible point on either side of the pair.        */

export type SegmentCtx = {
  chart?: Chart;
  p0: unknown;
  p1: unknown;
  p0DataIndex?: number;
  p1DataIndex?: number;
};

type PtLike = { readonly v?: number | null; readonly detach?: boolean };
type SeriesLike = readonly (PtLike | null | undefined)[];

/** The DATA index of one endpoint. Never a raw pixel comparison. */
export function segIndex(ctx: SegmentCtx, which: 0 | 1): number | undefined {
  const given = which === 0 ? ctx.p0DataIndex : ctx.p1DataIndex;
  if (typeof given === "number" && Number.isFinite(given)) {
    return Math.round(given);
  }

  const pt = (which === 0 ? ctx.p0 : ctx.p1) as
    | { x?: unknown; parsed?: { x?: unknown } }
    | undefined;

  const parsed = pt?.parsed?.x;
  if (typeof parsed === "number" && Number.isInteger(parsed)) return parsed;

  // last resort: invert the pixel through the x scale
  const px = pt?.x;
  const axis = ctx.chart?.options?.indexAxis === "y" ? "y" : "x";
  const scale = ctx.chart?.scales?.[axis];
  if (typeof px === "number" && typeof scale?.getValueForPixel === "function") {
    const v = scale.getValueForPixel(px);
    if (typeof v === "number" && Number.isFinite(v)) return Math.round(v);
  }
  return undefined;
}

export interface SpanOpts {
  /** Dash a connector that spans more than this many slots. */
  readonly slots?: number;
  readonly dash?: number[];
  /** Dashed differently when the connector bridges `[a, b]`. */
  readonly holiday?: (a: number, b: number) => boolean;
  readonly holidayDash?: readonly number[];
}

/**
 * Style a segment from the SERIES, so a connector is measured end to end:
 * `[a, b]` are the nearest visible (non-null, non-detached) points enclosing
 * the pair being evaluated. Pairs inside one connector therefore resolve to
 * one identical style and are drawn as one dashed run, not as loose pairs.
 */
export function spanSegment(series: SeriesLike, opts: SpanOpts = {}) {
  const n = series.length;
  const slots = opts.slots ?? 1;
  const dash = opts.dash ?? [6, 4];

  const shown = (i: number): boolean => {
    const p = series[i];
    return !!p && p.v != null && p.detach !== true;
  };

  const connector = (i0: number, i1: number): [number, number] | undefined => {
    let a = Math.max(0, Math.min(i0, i1));
    let b = Math.min(n - 1, Math.max(i0, i1));
    while (a > 0 && !shown(a)) a--;
    while (b < n - 1 && !shown(b)) b++;
    if (!shown(a) || !shown(b) || b <= a) return undefined;
    return [a, b];
  };

  return {
    borderDash: (ctx: SegmentCtx): number[] | undefined => {
      const i0 = segIndex(ctx, 0);
      const i1 = segIndex(ctx, 1);
      if (i0 === undefined || i1 === undefined) return undefined;

      const span = connector(i0, i1);
      if (!span) return undefined;
      const [a, b] = span;

      if (opts.holiday?.(a, b)) return [...(opts.holidayDash ?? [1.5, 3])];
      return b - a > slots + 0.01 ? [...dash] : undefined;
    },
  };
}

/** Pair-level dash for charts WITHOUT `spanGaps` (section C's episode charts).
 *  Where a dataset spans gaps, use `spanSegment` instead — a pair test cannot
 *  see the connector that will actually be stroked. */
export const gapSegment = (slots = 1, dash: number[] = [6, 4]) => ({
  borderDash: (ctx: SegmentCtx): number[] | undefined => {
    const i0 = segIndex(ctx, 0);
    const i1 = segIndex(ctx, 1);
    if (i0 === undefined || i1 === undefined) return undefined;
    return Math.abs(i1 - i0) > slots + 0.01 ? dash : undefined;
  },
});

const live = new Set<Chart>();

export const track = <T extends Chart>(chart: T): T => (live.add(chart), chart);

export function destroyAll(): void {
  for (const chart of live) {
    try {
      chart.destroy();
    } catch (err) {
      console.error("[chart] destroy failed", err);
    }
  }
  live.clear();
}
